<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Mortgage Calculator Online','description'=>'Estimate mortgage payments, interest and total cost.','url'=>'https://smarttoolz.in/tools/mortgage-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Mortgage Calculator</h1><p>Estimate your monthly mortgage payment.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Loan amount<input id="a" type="number" value="1000000"></label><label>Annual interest %<input id="r" type="number" step="0.01" value="8"></label><label>Years<input id="y" type="number" value="20"></label><button id="go" class="tool-btn">Calculate</button><p id="o"></p></div></section></main><script>go.onclick=()=>{let P=+a.value,n=+y.value*12,r=+document.getElementById('r').value/1200,m=r?P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1):P/n;o.textContent=`Monthly: ${m.toFixed(2)} · Total: ${(m*n).toFixed(2)} · Interest: ${(m*n-P).toFixed(2)}`};go.click()</script><?php smarttoolz_tool_page_end(); ?>